public class TicketSourceTask extends SourceTask {
    private static final Path CURSOR_FILE = Path.of("/tmp/ticket-cursor");
    private TicketApi api;
    private String topic;
    private String cursor;

    @Override
    public void start(Map<String, String> props) {
        api = new TicketApi(props.get("api.url"));
        topic = props.get("topic");
        cursor = Files.exists(CURSOR_FILE) ? readQuietly(CURSOR_FILE) : "";
    }

    @Override
    public List<SourceRecord> poll() {
        Page page = api.changes("eu", cursor, 500);
        List<SourceRecord> out = new ArrayList<>();
        for (Ticket t : page.items()) {
            out.add(new SourceRecord(null, null, topic, Schema.STRING_SCHEMA, t.json()));
        }
        cursor = page.nextCursor();
        writeQuietly(CURSOR_FILE, cursor);
        return out;
    }

    @Override
    public void stop() { }
}

