    .aggregate(SessionSpan::new, (k, v, agg) -> agg.add(v),
               Materialized.with(Serdes.String(), spanSerde))
    .toStream()
    .to("session-spans", Produced.with(Serdes.String(), spanSerde));

KafkaStreams streams = new KafkaStreams(builder.build(), props);
streams.start();

